rows=[]
for i,line in enumerate(RAW.strip().splitlines(),1):
    dept,subject,topic,en,tg,example,formula,mistake,q,a=line.split('|')
    rows.append(dict(id=f'ENG-{i:04d}',department=dept,subject=subject,topic=topic,university=None,regulation=None,semester=None,unit=None,subject_code=None,content_type='concept_note',explanation_en=en,explanation_thanglish=tg,worked_example=example,formula=formula,common_mistake=mistake,quiz=dict(question=q,answer=a),source=dict(type='synthetic',title='PRIYAN Notes AI authored starter',url=None,page=None,license='CC0-1.0',review_status='unreviewed'),split='train',version=1))
ROOT.joinpath('data/concepts.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
ROOT.joinpath('data/concepts.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')
with ROOT.joinpath('data/concepts.csv').open('w',encoding='utf-8',newline='') as f:
    fields=['id','department','subject','topic','explanation_en','explanation_thanglish','worked_example','formula','common_mistake','source_type','review_status']
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
    for r in rows:w.writerow({**{k:r[k] for k in fields if k in r},'source_type':r['source']['type'],'review_status':r['source']['review_status']})
# Derived views are not additional unique concepts. Grouped by concept ID for future splitting.
with ROOT.joinpath('data/instructions.jsonl').open('w',encoding='utf-8') as f:
    for r in rows:
        for lang,key in [('English','explanation_en'),('Thanglish','explanation_thanglish')]:
            f.write(json.dumps(dict(concept_id=r['id'],split=r['split'],synthetic=True,review_status='unreviewed',messages=[dict(role='user',content=f"Explain {r['topic']} in {lang}."),dict(role='assistant',content=r[key]+'\n\nExample: '+r['worked_example']+'\nFormula: '+r['formula']+'\nCommon mistake: '+r['common_mistake'])]),ensure_ascii=False)+'\n')
manifest=dict(unique_concepts=len(rows),derived_instruction_examples=len(rows)*2,departments=sorted(set(r['department'] for r in rows)),official_syllabus_coverage='NOT VERIFIED; no university/regulation assigned',synthetic=True,reviewed_records=0,license='CC0-1.0 for starter content only',sha256=hashlib.sha256(ROOT.joinpath('data/concepts.jsonl').read_bytes()).hexdigest())
ROOT.joinpath('data/manifest.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps(manifest,indent=2))
